      for(const {object,properties} of changes)object.nativeProperties=properties;runtimePreparation?.reapplyNativeBuild(existing,{...built,header,source});for(const key of keys)runtimeBuilds.set(key,built);for(const binding of runtime.bindings)if(keys.includes(runtime.object(binding.self)?.blueprintAsset||runtime.object(binding.self)?.nativeBuildAsset))binding.root.native={...built.metadata,header,source,headerPath,sourcePath};
      if(owner){owner.view.nativeMetadata={...built.metadata,header,source,headerPath,sourcePath};owner.view.nativeBuild={...built,header,source};owner.view.nativeDiagnostics='공개 상태 유지 재적용';blueprintWorkspace.nativeMetadata.set(owner.path,owner.view.nativeMetadata);}applied=true;
