let diskPolling=false;const diskModified=new Map();
async function receiveDiskDocument(doc,data){
  const before=structuredClone(doc.data);if(doc.dirty)doc.history.push({kind:doc.kind,data:before});else{doc.history=[];doc.future=[];}
  doc.data=structuredClone(data);doc.saved=JSON.stringify(data);doc.dirty=false;delete doc.view.nativeBuild;delete doc.view.nativeMetadata;
  if(doc.kind==='blueprint')await blueprintWorkspace.prepare(doc.path,data);
  if(doc.path===assetDocs.active)activateDocument(doc.path,true,false);renderDocumentTabs();queueRecovery();
}
function showDiskConflict(doc,disk,draft=doc.data){
  if(doc.view.diskConflict)return;doc.view.diskConflict=true;const dialog=document.createElement('dialog');dialog.className='close-document-dialog';
  const title=document.createElement('h2');title.textContent=assetTitle(doc.path)+' · 외부 변경';dialog.append(title);const controls=document.createElement('footer'),message=document.createElement('p');message.setAttribute('role','status');dialog.append(message);
  const finish=()=>{dialog.close();dialog.remove();doc.view.diskConflict=false;delete doc.view.recoveredDraft;renderDocumentTabs();queueRecovery();};
  for(const [label,key] of [['디스크 것 받기','disk'],['내 것 저장','mine'],['비교','compare']]){const button=document.createElement('button');button.textContent=label;button.onclick=async()=>{
    if(key==='compare'){if(!dialog.querySelector('.disk-compare')){const views=document.createElement('div');views.className='disk-compare';for(const [name,value] of [['내 편집',draft],['디스크',disk]]){const area=document.createElement('textarea');area.readOnly=true;area.ariaLabel=name;area.value=doc.kind==='text'?value:JSON.stringify(value,null,2);views.append(area);}dialog.insertBefore(views,controls);}return;}
    button.disabled=true;try{
      if(key==='disk')await receiveDiskDocument(doc,disk);
      else{const oldSaved=doc.saved,oldData=doc.data;doc.saved=JSON.stringify(disk);doc.data=structuredClone(draft);try{await assetDocs.save(doc,(path,text,expected)=>editorRequest('/api/asset/write',{method:'POST',body:JSON.stringify({path,text,expected})}));}catch(error){doc.saved=oldSaved;doc.data=oldData;throw error;}propagateMaterialFunctions([doc]);if(doc.kind==='blueprint')await blueprintWorkspace.prepare(doc.path,doc.data);if(doc.path===assetDocs.active)activateDocument(doc.path,true,false);}
      finish();
    }catch(error){message.textContent='저장하지 못했어요: '+error.message;}finally{button.disabled=false;}
  };controls.append(button);}dialog.append(controls);dialog.addEventListener('cancel',event=>event.preventDefault());document.body.append(dialog);dialog.showModal();
}
async function pollOpenDocuments(){
  if(diskPolling||authoringBatchBusy||running||startingPlay||closingEngine)return;diskPolling=true;
  try{
    const files=(await(await editorRequest('/api/project?recursive=1')).json()).entries,index=new Map(files.map(file=>[file.path,file]));captureDocument();
    for(const doc of assetDocs.items.values()){
      if(doc.building||doc.view.diskConflict)continue;const file=index.get(doc.path);if(!file)continue;
      const old=diskModified.get(file.path);diskModified.set(file.path,file.modified);
      if(doc.view.recoveredDraft){const response=await editorRequest(fileUrl(doc.path)),disk=doc.kind==='text'?await response.text():await response.json();showDiskConflict(doc,disk,doc.view.recoveredDraft);continue;}
      if(old===undefined||old!==file.modified){const response=await editorRequest(fileUrl(doc.path)),data=doc.kind==='text'?await response.text():await response.json();if(!validAsset(doc.kind,data)){notify('외부 파일 검증 실패: '+doc.path);continue;}if(JSON.stringify(data)!==doc.saved){if(doc.dirty)showDiskConflict(doc,data);else await receiveDiskDocument(doc,data);}}
      if(doc.kind!=='blueprint'||doc.view.diskConflict)continue;const native=doc.data.native||blueprintWorkspace.view(doc.path,doc.data).native;if(!native?.headerPath||!native.sourcePath)continue;
      const modified=Object.fromEntries([native.headerPath,native.sourcePath].map(path=>[path,index.get(path)?.modified]));if(JSON.stringify(modified)===JSON.stringify(doc.view.sourceModified))continue;
      const header=await(await editorRequest(fileUrl(native.headerPath))).text(),source=await(await editorRequest(fileUrl(native.sourcePath))).text(),metadata=parseNativeHeader(header);
      doc.view.sourceModified=modified;doc.view.nativeMetadata={...metadata,header,source,headerPath:native.headerPath,sourcePath:native.sourcePath};if(doc.data.native)blueprintWorkspace.nativeMetadata.set(doc.path,doc.view.nativeMetadata);await blueprintWorkspace.prepare(doc.path,doc.data);delete doc.view.nativeBuild;
      if(doc.path===assetDocs.active){graphs.blueprint=blueprintWorkspace.view(doc.path,doc.data);graphs.blueprint.native=doc.view.nativeMetadata;nativeBuild=null;renderNativeRegistry();renderBlueprintSidebar();renderBlueprintGraph();}
    }
  }catch(error){log('외부 변경 확인 실패: '+error.message,'ERROR');}finally{diskPolling=false;}
}

setInterval(pollOpenDocuments,2000);

